import json,sys,glob,os
R=sys.argv[1]
def flat(o,p=""):
    if isinstance(o,dict):
        for k,v in o.items(): yield from flat(v,p+"/"+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): yield from flat(v,p+f"[{i}]")
    else: yield p,o
